    /** Re-settle a SETTLED claim at its figure today; only a steward. */
    @PostMapping("/claims/{claimId}/resettle")
    public ClaimView resettle(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
